        JDialog youth=null;for(int i=0;i<100&&youth==null;i++){robot.delay(100);for(Window window:Window.getWindows())if(window instanceof JDialog&&window.isShowing()&&findField(((JDialog)window).getContentPane(),"FR") instanceof JTable){youth=(JDialog)window;break;}}if(youth==null)for(Window window:Window.getWindows())System.out.println("WINDOW "+window.getClass().getName()+" showing="+window.isShowing()+" title="+(window instanceof Frame?((Frame)window).getTitle():((window instanceof JDialog)?((JDialog)window).getTitle():""))+" content="+(window instanceof RootPaneContainer?((RootPaneContainer)window).getContentPane().getComponentCount():-1));check(youth!=null,"Times HW opens the native academy dialog");JPanel panel=(JPanel)youth.getContentPane().getComponent(0);JTable table=(JTable)Data.get(panel,"FR");JButton promote=(JButton)Data.get(panel,"FQ");check(table.getRowCount()==remoteAcademyBefore.size(),"Academy rows belong to the remote seller");check(remoteSeller.ky().equals(remoteAcademyBefore),"Viewing a remote academy must not mutate the shared seller shell");check(!promote.isEnabled(),"A remote club's academy cannot be promoted by this buyer");check(!((JButton)Data.get(panel,"FP")).isEnabled()&&!((JButton)Data.get(panel,"FN")).isEnabled()&&!((JButton)Data.get(panel,"FO")).isEnabled(),"Unsupported remote academy mutations remain disabled");
